const db = require('better-sqlite3')('/workspace/world.db');

// Get product details
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('=== PRODUCT ===');
console.log(JSON.stringify(product, null, 2));

// Check for variants
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-73FAB4'\").all();
if (variants.length) {
  console.log('\n=== VARIANTS ===');
  console.log(JSON.stringify(variants, null, 2));
}

// Check for warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE product_id = 'PROD-73FAB4'\").all();
if (warranties.length) {
  console.log('\n=== WARRANTIES ===');
  console.log(JSON.stringify(warranties, null, 2));
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Look up compatible products
const compatIds = ['PROD-B98D14','PROD-FA0948','PROD-2DBA15','PROD-7C0240'];
const compatProducts = db.prepare('SELECT product_id, name, price FROM products WHERE product_id IN (' + compatIds.map(()=>'?').join(',') + ')').all(...compatIds);
console.log('=== COMPATIBLE PRODUCTS ===');
console.log(JSON.stringify(compatProducts, null, 2));
"

